(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,191232,e=>{"use strict";var i=e.i(843476),l=e.i(811337);function s(e){let s={li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:h,AnketaProse:j,Whisper:x}=s;return r||n("AnketaCollapse",!0),c||n("AnketaGroup",!0),d||n("AnketaList",!0),h||n("AnketaPoint",!0),j||n("AnketaProse",!0),x||n("Whisper",!0),(0,i.jsxs)(c,{children:[(0,i.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,i.jsxs)(d,{children:[(0,i.jsxs)(h,{title:"Имя персонажа [русс|англ]",children:[(0,i.jsx)(s.p,{children:(0,i.jsx)(s.strong,{children:"Иероним Анагносту | Hieronymus Anagnostu"})}),(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"«Ткач Отражений» — прозвище, закрепленное за Иеронимом ввиду определенной специфичности используемых им магических способностей, а также ритуалов, в большинстве своем, связанных с зеркалами и явлениями, близкими с ними;"}),"\n",(0,i.jsx)(s.li,{children:"«Господин Калейдоскоп» — прозвище, полученное после вступления в ряды НАЭ за многочисленные исследования в области атрибутов Системы Соломона, создания «адуляра», его дальнейшую модификацию и ИКР (Индуктор Контролируемого Распада)."}),"\n"]})]}),(0,i.jsx)(h,{title:"Возраст",children:(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"прожитый на земле: 49 лет."}),"\n",(0,i.jsx)(s.li,{children:"дата рождения — 12.04.1525г. | смерти — 25.10.1574г."}),"\n",(0,i.jsx)(s.li,{children:"прожитый в Загробном мире как грешная душа: 444 года."}),"\n"]})}),(0,i.jsx)(h,{title:"Пол",children:(0,i.jsx)(s.p,{children:"Мужской"})}),(0,i.jsxs)(h,{title:"Раса",children:[(0,i.jsx)(s.p,{children:"Сирена (Антропоморфная амфибия | Жаба)."}),(0,i.jsxs)(s.ul,{children:["\n",(0,i.jsx)(s.li,{children:"Меланхолия уныния привычная для всех сирен в исполнение Иеронима проявляется в форме накатывающих приливов разочарования пропитанной легкой, но ощутимой усталостью рутинного водоворота нескончаемых предстоящих дел. В такие моменты сильнейший обжигающе ледяной гнев, наконец-то прорывающийся сквозь маску терпения, раздражение на чужую некомпетентность, планы возмездия глупцам, бросившим открытый вызов авторитету Ассоциации – растворяются, становятся незначительными, в конечном итоге забываясь в уныние привычного;"}),"\n",(0,i.jsx)(s.li,{children:"Подобно двойственность природе амфибии способной жить, как на суше, так и в водных глубинах, но истинно до конца не принадлежащей обоим мирам Ткач Отражений разделен между собственным родом, коей ритуалом его инициации был возвращен из небытия истории, и Научной Ассоциацией Энкража, горячо любимой им вместе с тем возглавляемой. Долг возродителя Отблеска Нарцисса сталкивался с желанием возвышения НАЭ, где связь с первым хоть не была разорвана, но значительно ослаблена, по сравнению с укреплением позиции в качестве Верховного Арбитра. Превращение Дворца Стеклянных Глаз в базу Ассоциации лишь подтверждает это;"}),"\n",(0,i.jsx)(s.li,{children:'Еще при жизни темперамент Анагносту был подобен неизведанным темным океанским глубинам обманчиво сокрытым под мирной лазурной гладью, сколь спокойно не была поверхность, никогда не знаешь, какой шторм сокрыт под ней. Сколько бы улыбок мужчина не дарил людям, насколько бы не раскрывал душу пред "друзьями", сколь простым бы не казалось составить представление о его личности, лишь немногим в конечном итоге было дано узреть «настоящего» Иеронима. Обремененного временами внезапно, словно постоянно меняющейся погоде на морских просторах, возникающей по-настоящему отвратной театральность, в приступах, которой мужчина способен буквально утопить несчастного слушателя в нескончаемых излишне драматичных речах и чрезмерно пафосных размышлениях. Запятнанный черной завистью направленной на всех кто не входит в круг его подопечных, тех, кого Господин Калейдоскоп, в некотором смысле уподобляясь юному себе, считает недостойными достижений, закрепленными за ними, недостойными даже сохранится в чужой памяти;'}),"\n",(0,i.jsx)(s.li,{children:"С другой стороны Ткач Отражений настолько погряз во множестве собственных масок, что даже сам не сможет наверняка сказать, где фальшь переходит в истинное эго. Впрочем, вернее будет сказать, Иероним никогда не знал – каково внутренние «я» принадлежащее ему: за все столетия жизни, за существование на Земле и в Энкраже он даже близко не приблизился к разгадке, вычленяя лишь отдельные фрагменты собственной принадлежности. Более того его жабья форма антропоморфной амфибии не принадлежит к реально существующему в мире живых виду, являясь лишь искореженным отражением, столь иронично явно подчеркивая связь с родом Отблеск Нарцисса множество веков назад потерявшего собственную идентичность во мраке."}),"\n"]})]})]})}),(0,i.jsxs)(r,{title:"Психологический профиль",children:[(0,i.jsx)(r,{title:"Характер",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Интеллигентность, тактичность, спокойствие и планомерность – именно эти черты характера без промедлений приходят на ум практически любому грешнику хоть раз узревшему Верховного Арбитра Научной Ассоциации. Его спокойствие на первый взгляд граничит с безмятежность монахов, вот только в истине оно столь же обманчиво сколь мирная озёрная гладь, таящая в глубине губительные подводные течения, ибо трещит по швам едва ли не от каждого раздражителя, сдерживаясь от зловещего проявления лишь благодаря по-настоящему титаническому терпению. А список возможных раздражителей более чем обширен: назойливые расы похоти, за исключение разве что наг в связи с расовой симпатией, откровенные глупцы, не понимающие очевидных истин, гордецы с раздутым самомнением, не подкрепленным ничем, шуты пытающиеся строить из себя великих интриганов, не осознавая насколько жалки их манипуляции и многое другое. Но ранее упомянутый самоконтроль совершенно не мешает мысленно сотню раз проклясть до третьего колена причину очередной головной боли желая жестокую смерть и размышляя о кровавом возмездии, впрочем, уже спустя несколько секунд прежние мысли обращается в небрежное разочарование окутанное легким слоем усталости, прежде чем окончательно угаснуть средь бесконечных дел. Хотя есть несколько исключений, тем способных расколоть привычную маску спокойствия: НАЭ, ее участники, прямое оспаривание позиции Иеронима и Архивариусов; правильная расстановка данных положений в словесной провокации — конец терпению Господина Калейдоскопа, ярости или полноценного срыва ни в коем случае не будет, лишь ледяная злоба разбавленная ядом сочащемся в каждом слове, да дамоклов меч, ожидающий своего часа. Мужчине в принципе не свойственно проявлять ярость в форме беспорядочного буйства, подобные эмоции всегда заточенный инструмент, отступлением от вышеупомянутого утверждения составляет только открыто выражаемое раздражение редко проявляющиеся вне бурной реакции подкрепленной сарказмом. Названное проявление гнева подводит к другой части личности Анагносту – планомерности скрепленной прекрасной адаптивностью, в хорошем иль отвратном расположении духа, в леденящей злобе или умиротворении, его разум всегда найдет способ включить ситуацию в паутину собственных планов. Любая информация будет упорядочена, классифицирована и структурирована, чтобы послужить новым кирпичиком в замыслах. Столетия, проведённые в Энкраже, совокупно с наивысшим рангом в Ассоциации только укрепил сие черту, к сожалению, вместе с ее негативной стороной - порой в длительном ожидании Ткач Отражений чрезмерно зацикливается на сплетениях задумок воображая ложные сценарии, рожденные в попытках найти второе дно так, где его нет, природная недоверчивость лишь усугубляет ситуацию. К тому же в долгосрочной перспективе, когда существует несколько равноценных вариантов, мужчина часто проявляет нерешительность, на долгие часы, погружаясь в тягучие раздумья."}),(0,i.jsx)(s.p,{children:"Тактичность личностное качество само собой разумеющееся для персоны занимающей ранг Верховного Арбитра, в конце концов, разве можно не обладая способность соблюдать даже базовый этикет общения получить приемлемое финансирование? Конечно же, нет. А чувство такта Господина Калейдоскопа совместно с его социальными навыками на несколько ступеней превосходят термин «базовые», редко в Энкраже найдешь столь приятного собеседника: интеллигентный гармоничный говор, практически аристократичный, но лишенный жеманности. Способный поддержать практически любой разговор благодаря обширным хоть не слишком углубленным знаниям во множестве сфер одновременно с тем с радостью готовый стать слушателем. Ко всему прочему Ткач Отражений достаточно проницателен, дабы ещё в тусклой искре заметить зарождающееся напряжение в диалоге, затушив ее, соскользнув на новую тему иль наоборот разжечь, в надежде подтолкнуть на необдуманные поступки. А льстивые речи вызывающие только брезгливое раздражение, сорвавшись с его уст, станут самым приятным из комплиментов, сущность сирены лишь способствует этому."}),(0,i.jsx)(s.p,{children:"Впрочем, Анагносту далеко не серый кардинал одними лишь тирадами закручивающий сложные тенета интриг, несомненно, он подобно большинству сирен наслаждается манипуляциями и удачная махинация, подталкивающая случайного грешника в незнании следовать подготовленному сценарию, в заблуждении считая его собственной волей, принесет ему немалое удовольствие. Но сколь притягательны, забавны и занимательны не были данные деяния, в виденье мужчины подобные манипуляции, вплетенные в серьезные ситуации прямой путь к усугублению проблемы, бомба замедленного действия в один момент способная обрушить весь закрепленный результат. Иногда простой прямолинейный путь, самый эффективный. К тому же, Иероним соответствуя статусу главы нейтральной фракции, предпочитает, придерживается одноимённой позиции, во многих событиях происходящих между организациями оставаясь безучастным наблюдателем, или действуя в роли посредника пытаясь не допустить возникновения конфликта, а при его возникновении привести к деэскалации вместе с установкой приемлемых компромиссов. Ибо прямая конфронтация между фракциями, тем более долговременная, имеющая потенциал разгореться в пожар раздора последнее, что нужно Энкражу. Единственным исключением вышесказанного непосредственная вовлеченность Научной Ассоциации в подобном сценарии можно узреть Верховного Арбитра с другой стороны. Ведь фаворитизм по отношению к «ненаглядным искоркам», как иногда нарекает Анагносту учёных находящихся под покровительством НАЭ, очевиден: в представление мужчины его люди не способным совершать проступков, все это лишь небольшие случайные убытки или вина другой стороны. По этой причине он будет крайне рьяно отстаивать позицию собственной фракции, с большим нежеланием идя на уступки и с еще большим отторжением принимая во внимания позицию противоположной стороны. Доказательства против его подчиненных в таких случаях должны быть по-настоящему неопровержимые, ибо все меньшее будет презрительно откинуто в сторону, слишком большое доверие оказывается к младшим коллегам. С другой стороны насколько сильно Господин Калейдоскоп лелеет своих сотрудников, настолько же он строг к ним: основополагающие принципы Ассоциации незыблемы, если вина очевидна суровое, в некоторых смысле даже жестокое, наказание будет приведено в исполнение в кратчайшие сроки, в конце концов, Ткач Отражений больше всего ненавидит, когда его доверие предают. Ложь ему в лицо тоже не прибавляет балов, хоть сирена относиться к этому несколько небрежно. Кроме того насколько не была бы сильна привязанность к каждому из подчиненных в частности, благополучие НАЭ в целом всегда будет приоритетнее в связи с тем выбор между жизнью членов нижнего среднего эшелона и выдачей ценного артефакта/засекреченной информации очевиден. Честь для ученого отдать свою жизнь во имя благополучного процветания науки."}),(0,i.jsx)(s.p,{children:"Хотя в сказанном ранее утверждении о ненависти ко лжи можно найти некоторое лицемерие, так как самому Иерониму присущи частые недомолвки вместе с практически патологической лживостью формирующей нескончаемый слой масок за коими прячется «настоящий» Анагносту. В прочем «настоящий» слишком сильное слово, ибо даже он сам не до конца уверен в подлинности этого амплуа. Вечно сетующий на бездарность молодежи, в моменты впадающий в приступы утомительной для любого нормального грешника театральности грозящей обрушиться литрами бессмысленных чрезмерно пафосных изречений действующих не хуже любого снотворного, по отечественному относящийся чуть ли не к каждому участнику Научной Ассоциации. Впрочем, в этой любви не все равны: независимые ученые получают больше всего благосклонности, поскольку их верность НАЭ не колеблется принадлежностью к другой фракции, к тому же мужчина чувствует некоторую сентиментальную ностальгию вспоминая начало своего пути. Реальты и вальгарды разделяют второе место, первые симпатизируют четкой подчиненности правилам и законам царящим внутри их фракции подкрепленной преданностью замку, кроме того люди отправленные Эрнестом уже достойны расположения, вторые же в некоторой степени разделяют исследовательский дух Ассоциации."}),(0,i.jsx)(s.p,{children:"Членов же Черного Рынка можно обозвать «приемышами», Ткач Отражений не то чтобы недолюбливает их, просто видит по большей мере самовлюбленных детей, несомненно, талантливых, но в своем бунтарском духе напрасно считающих себя способными бросить вызов законам Энкража. Между тем подобное отношение вытекает в удобное для Чёрного рынка закрытие глаз на определенные сомнительные исследования, конечно до тех пор, пока они не нарушают базисные правила Научной Ассоциации. Упрямство ещё одна черта характера, проглядывающаяся в личности Господина Калейдоскоп. Притом данная особенность натуры в разных ситуациях может варьироваться от зыбкого убеждения способного дрогнуть даже под незначительной аргументацией до непоколебимого принципа, отстаиваемого до самого конца. Продолжая разговор о положительных личностных характеристиках Иеронима, стоит упомянуть доброту, сопряженную с милосердием, выраженным во вторых шансах щедро даруемых провалившимся подопечным еще способным на реабилитацию, впрочем, не стоит заблуждаться, подобное снисхождение столь же мимолетно сколь фальшиво, одна ошибка и оно смениться равнодушной жестокостью. Более того сирена предоставляет шанс лишь при полной уверенности в контроле над протеже, а также достаточной потенциалом использования во благо НАЭ, к тому же несчастливчик подходящий под представленные условия будет считаться не более чем удобной пешкой осуществления планов. Вдобавок предыдущее положение подкрепляется полным отсутствием всякой эмпатии вне круга личных подчиненных Анагносту, подобное отношение прекрасное подспорье для формирования прагматичных замыслов не испорченных излишними чувствами. Жажда знаний погубила Иеронима во время жизни, сделал ли он выводы? Определенно нет. Мужчина все еще одержим поиском новых знаний, каждая новая информация, каждое новое исследование приносит ему необычайное удовольствие, он жадно ищет все новые и новые познания, больше разжигая аппетит собственного разума. Исходя из предыдущего тезиса, Ткач Отражений искренне наслаждается сражения, конечно же, предпочитая, оказывается зрителем вне зоны опасности, ибо нет лучше способа оценить возможности другого грешника, найти вдохновение на новое изыскания одновременно с тем пополнив безмерный архив Научной Ассоциации очередными витком информации. По этой же причине в момент прямой конфронтации не стоит ожидать от него хоть намека на благородство, он лишен подобного из-за чего с легкостью прибегает к подлым трюкам и шантажу, в конце концов, Арбитр ученый, не доблестный воин."})]})}),(0,i.jsx)(r,{title:"Страхи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Лиссофобия",children:(0,i.jsx)(s.p,{children:"Впасть в безумие один из сильнейших страхов Иеронима, участь куда страшнее самой жестокой из смертей. Для мужчины интеллект всегда был его путём продвижения, самым опасным оружием; сумасшествие сделает из него рудимент для Ассоциации, дестабилизирует её работу. Кроме того само представление существования собственного эго в его глазах определяется критерием разума."})}),(0,i.jsx)(h,{title:"Развал Научной Ассоциации",children:(0,i.jsx)(s.p,{children:"НАЭ один из фундаментальных смыслов существования Господина Калейдоскопа в Энкраже, её упадок обозначал бы полный провал мужчины как главы Ассоциации и потеря основного смысла встречать новый день."})}),(0,i.jsx)(h,{title:"Забвение",children:(0,i.jsx)(s.p,{children:"Исчезновение всякого наследия вместе с воспоминаниями о Верховном Арбитре, худший из его кошмаров, ведь сие стечение обстоятельств обозначило бы полную бессмысленность всего его существования."})}),(0,i.jsx)(h,{title:"Повторения инцидента Скептиков Пятидесяти и Братства Крови",children:(0,i.jsx)(s.p,{children:"Трагедия, стоившая двух самых блистательных групп своего времени, до сих пор окутана завесой тайны, и её повторение стало бы катастрофой для Ассоциации."})})]})}),(0,i.jsx)(r,{title:"Мечты, цели",children:(0,i.jsxs)(j,{children:[(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Золотой век Научной Ассоциации."})," Подобно большинству Верховных Арбитров до него Иероним страстно грезит возвещать о вступлении НАЭ в новую веху развития, знаменующуюся беспрецедентными открытиями, полностью изменяющими привычный взгляд на действительность Энкража, столь же весомыми как исследования Соломона, Наследника Гоэтии и Лезимара."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Решение проблемы деградации ядра."})," Редукция «Короны» острая проблема для старых грешников, начало ее развития фактически смертный приговор, несомненно, отложенный на некоторое время, но все же, неизбежный. Решение данной проблемы стало бы одним из величайших открытий за все существование общества грешников, вместе с этим открыло бы для Анагносту куда больше времени на исследования мира после смерти."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Поддержание стабильности Научной Ассоциации."})," Прямая обязанность Иеронима в качестве главы Ассоциации, задача ради которой он готов пойти на самые отчаянные меры."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Совершить принципиально новое открытие в сфере системы Атрибутов Соломона."})," Господин Калейдоскоп не только лидер, но и ученый притом весьма амбициозный, потому нет ничего необычного в его желание совершить блестящее открытие в сфере изучаемой десятилетиями, приблизив собственное имя к Соломону."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Раскрытие тайны инцидента исчезновения Скептиков Пятидесяти и Братства Крови."})," Трагедия, стоившая двух самых блистательных групп своего времени до сих пор окутана завесой тайны и Иероним считает своим долгом во имя Ассоциации и науки собственноручно раскрыть её, заполучить сокрытое дурное наследие, а после навсегда похоронить эти тайны."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Поддержка начинаний подопечных НАЭ."})," Каждый из сотрудников Научной Ассоциации в глазах Анагносту искра уже ярко освещающая нынешнюю эпоху или имеющая потенциал вспыхнуть с силой звезды потрясся сложившуюся картину новым открытием. Их триумф – триумф Ассоциации, триумф Иеронима."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Запечатлеть себя в вечности."})," Личные научные достижения, возвышение Ассоциации, изыскания в надежде сохранить ядро и неудержимый поиск знаний – все это лишь пути выполнения самой сокровенной из всех целей Иеронима: преодолеть тщетность бытия, закрепляя смысл собственного существования в бессмертии тела или памяти."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Восстановить величие рода Отблеск Нарцисса."})," Как глава рода и личность ставшая причиной возвращения Обсидиана из пучины забвения долг Анагносту в полной мере восстановить потерянное наследие Отблеска Нарцисса вместе с позицией в Хоре. Кроме того Отблеск за последние столетия оказался глубоко интегрирован в Научную Ассоциацию и возвышения первого благоприятно отразиться на укреплении позиций второй."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Заполучить сборник, передаваемый между скинуокерами."})," Нынешний Верховный Арбитр, как вероятно большинство его предшественников, жаден до знаний и разузнав о предполагаемом существовании тщательно охраняемых знаниях передаваемых среди скинуокеров, он не мог не поставить пред собой цель заполучить их."]}),(0,i.jsxs)(s.p,{children:[(0,i.jsx)(s.strong,{children:"Заполучить «Драконье Сердце»."})," Жемчужины Лунов давний объект нездоровой заинтересованности Научной Ассоциации, Господин Калейдоскоп в этом плане совсем не исключение."]})]})}),(0,i.jsx)(r,{title:"Биография (при жизни)",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Дождливой ночью 12 апреля 1525 года, когда на землю опустилась шёлковая вуаль сгущающегося мрака разбавленного блеклым светом круглой луны обрамленной бескрайними звёздами, в одном из многочисленных домов живописной Венеции свой первый вздох совершил Иероним Анагносту."}),(0,i.jsx)(s.p,{children:"Он стал первенцем своего рода, его мать Маддалена Дандоло третья дочь именитого торговца и члена Большого совета, отец же Амвросий Анагносту бывший солдат, ветеран третьей турецко-венецианской войны, корни семьи коего уходили к побочной ветви византийской аристократической родословной."}),(0,i.jsx)(s.p,{children:"Детство Иеронима было двойственным: горячо любимый, с воодушевлением обожаемый своей матушкой и удостоенный сдержанной опеки отца, тем не менее, полностью лишенный истинной родительской привязанности. Ибо будущий Господин Калейдоскоп был далек от определения желанного ребенка, конечно явно не ошибка, но неожиданная случайность ещё больше усугубившей внутренний раскол, в конечном итоге взаимной любви в браке его родителей не было с самого начала. Маддалена больше увлеченная собственным будущим и слишком молодая дабы мыслить о делах любовных, тем более воспитании ребенка, а сердце Амвросия было исчерчено кровоточащими ранами пережитого на войне, излечить кои явно было вне возможности изнеженной богатством девчушки, впрочем, она даже не пыталась этого сделать."}),(0,i.jsx)(s.p,{children:"С самого начала сие венчание произошло лишь по прихоти патриарха рода Дантоло, который в порыве прихоти захотел связать свою родословную с благородной кровью, закрывая глаза на то, что звонкая монета в Венецианской Республике значила больше чем происхождение. То что Амвросий был лишь солдатом не сколько не волновало отца Маддалены, к тому же был нужен только для зачатья дитя, коему с самого начала полагалось стать, очередной побочной ветвью основной родословной принеся своим талантом или кропотливой работой пользу и величие."}),(0,i.jsx)(s.p,{children:"В обстоятельствах, царивших в доме, даже престарелый ментор, нанятый дедом Иеронима по материнской линии в желании воспитать достойного величия предков представителя родословной, был большей родительской фигурой в наивно задумчивых глазах ребенка. Впрочем, подобному никто не возражал: отец с матерью были не столь близки с собственным чадом, дабы заметить отрешенность, старый учитель предпочитал игнорировать сей факт, больше заботясь о выполнении собственной работы – обучения."}),(0,i.jsx)(s.p,{children:"Юный Иероним в некотором смысле воплощал образ идеального ребенка: тихий, требующий минимального внимания, достаточно самостоятельный для своих малых лет, усердный в учебе."}),(0,i.jsx)(s.p,{children:"С другой стороны чрезмерно закрытый, с момента первых прочитанных слогов предпочитающий книги постоянно пополняющейся милостью его деда домашней библиотеки играм с ровесниками, которые впрочем, разделяли подобное поведение, сторонясь, по их мнению, странного мальчишки, не вписывающегося в рамки привычного для них поведения. Но такого рода отчуждение нельзя было назвать полноценной изоляцией, остальные дети при случае всё ещё контактировали с Анагносту, просто старались свести взаимодействие к минимуму, или, же поспешно уходя после возникновения очередной неловкой тишины порожденной чрезмерным различием интересов. Тем не менее, его склонность к обособлению стало негативным наитием, посеявшим в душе семена гордыни сращенной с зарождающей завистью, кое лишь ожидали благой почвы, дабы расцвести в отвратительные бутоны греха."}),(0,i.jsx)(s.p,{children:"В конце мая 1537 года происходит первая встреча Иеронима со своим дедом по материнской линии, до этого известным лишь по многочисленным подаркам и поздравительным письмам. Мальчишка оказывается, более чем доволен данным событием, видя в старом родственнике фигуру для подражания, настоящее отображение семейной связи стоящие в оппозиции его родителям, а также надежную опору."}),(0,i.jsx)(s.p,{children:"В сентябре Маддалена и Амвросий совершенно неожиданно для младого разума собственного дитя совершают попытку вывести последнего из состояния изоляции, вложив правильные, по их мнению, интересы для ребенка его возраста. В конечном итоге попытка вызывала лишь большее отторжение со стороны будущего Господина Калейдоскопа. Два дня спустя прибывает патриарх рода Дандоло, вынося финальный вердикт: ”Норма или нет, меня не волнуют столь незначительные вещи! Пока мой внук демонстрирует потенциал стать достойным величия корней своей семьи и не очерняют мою репутацию, все остальное не требует внимания”."}),(0,i.jsx)(s.p,{children:"Отношения между Анагносту и его родителя охладевают, опускаясь до уровня, практически полного безразличия к существованию друг друга; Амвросий Анагносту все чаще проводит время вне дома, иногда пропадая на целые дни."}),(0,i.jsx)(s.p,{children:"В середине мая 1539 года в возрасте 14 лет с благословением, а также экономической поддержкой своего деда по материнской линии Иероним Анагносту раним утром отправился в однодневное путешествие, конечной целю которого, был цент просвещения Венецианской республики, славный град Падуя. Почему сын благородного состоятельного рода отправился пешим ходом, да еще в одиночку? Ответ был до банального простым: Иероним сбежал, заплатив возничему за молчание. Ибо это должно было быть его путешествием, его достижением, его открытием, его первым опытом за пределами стен библиотеки, позволить доставить себя так просто, позволить сопроводить себя значит лишить себя озарения, по крайне мере так твердил его юношеский максимализм."}),(0,i.jsx)(s.p,{children:"Несмотря на относительную непродолжительность данного маршрута, он оказался далеко не самым простым сразу по целому ряду факторов: во-первых, привыкший к книгам Иероним доказал собственную физическую неподготовленность к девяти часовому пути выдохнувшись уже спустя два часа. Во-вторых, под вечер того дня на протяжении нескольких километров близ города на землю сначала обрушился ливень, а после все укрыла густая пелена бледного тумана смешавшаяся со сгущающейся мглой заходящего солнца, сделав оставшуюся дорогу еще более трудной."}),(0,i.jsx)(s.p,{children:"Несмотря на физические неудобства доставленные путешествием юноша в противоположность своему физическому состоянию прибывает к стенам университета в состоянии полного восторга. Подобные кардинальные различия ментального и телесного состояния в тот день стали первым отблеском изменений созревавших в детском разуме – впервые в свое жизни будущему Господину Калейдоскопу открылось, насколько дивен был мир за пределами родного дома и воображаемой реальности книг. Несомненно, уже со следующим рассветом этот душевный подъем угаснет, теряясь в более захватывающих событиях, а подобные путешествия станут блеклой обыденностью, но воспоминания сохраняться до самого конца."}),(0,i.jsx)(s.p,{children:"Благодаря денежному пожертвованию в размере увесистого кисета полного цехинов, а также письмо закрепленное печатью патриарха рода восседающего в Большом совете глубоким вечером 1539 года Иероним становиться полноправным школяром артистического факультета Падуанского университета и размещается в его общежитии."}),(0,i.jsx)(s.p,{children:"Первые лекции, а также следующие за ними диспуты были встречены с энтузиазмом и не доставили юноше особых затруднений. Впрочем, прогресс в обучении на таком уровне был более чем очевиден – его готовили к обучению в институте с самого детства, врожденная тяга к знаниям, подкрепленная свободными часами, проведенными в окружении книг, лишь укрепила полученный от преподавателей базис знаний. Хотя, очевидно, не во всех предметах, встреченных в первые дни обучения он был одинаково хорош: грамматика в отличие от проходящих практически идеально занятий логики и с переменных успехом изучаемой риторики, вызывала некоторые затруднения. В виду некоторой нерешительности в правильности собственного письма на латыни, а также легким подсознательным отторжение идеи столь большой важности данной области."}),(0,i.jsx)(s.p,{children:"Вместе с этим в стенах Падуанского института Анагносту приобрел не только знания, но и первого одновременно с этим самого ближайшего друга – Жермена Трюдо, сына парижского священника изгнанного из родной Франции собственным отцом, узнавшим сколь богохульные мысли таяться в разуме его чада. Они привлекли внимание друг друга еще в первые дни, столь схожие по постепенно формирующему мировоззрению в их юношеском разуме, достаточно умные, дабы поддержать воодушевленный переполненный излишне вычурный научными терминами диалог другого. Формирование уз крепкой дружбы между Анагносту и Жарменом было неизбежно."}),(0,i.jsx)(s.p,{children:"Наряду с тем университет стал благой почвой для того чтобы посаженные ещё в детстве семена гордыни в полной мере разрослись в отвратительные побеги высокомерия. Скрытое за пеленой ложного спокойствия и саваном сладких речей презрение гноилось в душе Анагносту, прочие студенты казались слишком убогими в своем происхождении, в своих стремлениях, обделенные хоть каким-либо шансом претендовать на свое место в университете. Знакомство с Трюдо лишь укрепило пороки, ибо впервые в жизни Иерониму было с кем разделить ядовитую гниль, хранящуюся в сердце; спрятаться в безлюдных закоулках университета, дабы обсудить каждый услышанный слух правдивый, иль нет, порочащий имя ближнего и распространить его в массы с силой неудержимой лавины."}),(0,i.jsx)(s.p,{children:"К началу октября 1540 года благодаря к тому времени уже длительной дружбе с общительным по своей натуре и крайне харизматичным Жарменом Иероним приобретает множество самых разнообразных знакомств варьирующихся от портовых чернорабочих до юных наследников благородных родов. Хоть многих из них юноша призирал ещё более чем своих сокурсников, общение в столь разных кругах принесло точки зрения с другого угла на известные вещи, вместе с тем помогло куда лучше находить подход к людям, что не раз играло свою роль на протяжении всей жизни Анагносту и после ее завершения."}),(0,i.jsx)(s.p,{children:"За два дня до Рождества 1543 года в возрасте 18 лет уже юноша, а не мальчишка, будущий Господин Калейдоскоп успешно пройдя четыре года обучения в Падуанском институте, завершив Тривиум, приступил к одному из важнейших этапов в его жизни - получению статуса бакалавра искусств первой из двух ступеней к настоящему образованию. Диспут прошёл более чем идеально, ибо за 4 года учёбы на артистическом факультете Анагносту сформировал себе репутацию безупречного школяра, более того прекрасно осознавал что именно желает услышать от него преподаватель. Следующее за тем испытание пред магистрами факультета прошло столь же гладко, впрочем, иначе быть просто не могло, юноша был протеже влиятельного человека, имел с ним родственную связь, и слишком много жестов даяния было совершено его покровителем во благо института. Фортуна перестала улыбаться в момент заключительного публичного диспута, несомненно, Иероним получил степень бакалавра, но последнее выступление не было идеально, оно не стало триумфом, и во всем была вина наставника закрепленного за юношей на отставшие три года обучения, решившего умерить на его взгляд горделивого ученика."}),(0,i.jsx)(s.p,{children:"Спустя три месяца обида все еще не была забыта, лишь разгорелась пуще прежнего от злобной ревности снедающей Анагносту, от мыслей, что удача с наставниками помогла другим более презренным, недостойный достичь лучшего результата. В апреле 1544 года бурлящие в разуме эмоции наконец-то нашли способ проявиться в форме столь привычной для Иеронима – в тот день каждая шавка на улицах Падуи знала Маттео Каррера, преподаватель артистического факультета, прямо на кануне бракосочетания, изменил своей невесте в содомской оргии. Абсолютный вымысел, но голодному до зрелищ народу нужна была не правда, а кровь; к тому же, в Падуе оказалось много людей желавших превратить искры слухов в пожар бешенства толпы. Ушлый торговец, увидевший в этом прекрасною возможность организовать новую лавку на месте проживания Маттео чей дом к несчастью последнего расположился в столь удачном для торговли месте, капитан стражи, оказавшиеся в сговоре с торговцем за несколько дукатов закрыв глаза на ползучие шептания. Парочка озлобившихся студентов, решивших преподать урок, ненавидимому преподавателю разнося слухи по кабакам, непросыхающий пьяница, продавший скандальную историю за кружку свежего пенного. Терзающая душу злоба Анагносту наконец потухла в удовлетворении."}),(0,i.jsx)(s.p,{children:"В конце апреля 1544 года за Иеронимом, взамен пропавшего без вести в ходе беспорядков Маттео Каррера, был закреплен новый наставник – Антонио Галло магистр искусств, чей возраст давно перевалил за сорок лет. Несколько дней стало достаточно, дабы старик успел привязаться к своему новому протеже: спокойный, стремящийся к знаниям, далекий от совершенства, но быстро учащийся на собственных ошибках, а главное послушно соглашающийся с незыблемыми истинами научных догм."}),(0,i.jsx)(s.p,{children:"Месяцы пролетали незаметно, изучения квадривиума проходило более чем гладко, и все больше юноша задумывался какой высший факультет избрать впоследствии. Неопределенность укоренялась в разуме Анагносту, погружая в пучину нерешительности, прежде чем, достигнув апогея разрешиться в дождливую ночь 28 сентября 1545 года в грязной дешевой таверне, куда Иероним был затянут своим дорогим другом. Там с презрением, скрываемым за спокойным добродушием, он наблюдал за напивавшимися «коллегами» по студенчеству одновременно с тем следя, дабы Жармен не перебрал с алкоголем, перешептываясь с ним о свежих сплетнях. В оном подобии спокойствия могла пройти вся оставшаяся ночь, вот только идиллию нарушила разбушевавшаяся компания школяров, что пытались напоить брыкающегося юнца, смутно знакомого бакалавру. Знакомое раздражение с новой силой распылялось в душе Иеронима, пока привычная улыбка дрогнула, в злобе растягиваясь шире, впрочем, подобное выражение быстро сменилось шоком, стоило оглушительному кашлю разойтись по заведению. Юношу, коему еще несколько мгновений назад вливали в глотку алкоголь, ныне рвало, но не как обычного пьяницу, звук был хриплым болезненным натужным. Пока остальные посетители панически метались, иль безучастно продолжали пить, Иероним Анагносту замер в оцепенении, потерянно наблюдая, как румяная кожа становиться синюшной, прежде чем несчастный бездыханным трупом не упал в лужу собственной рвоты. Впервые он узрел смерть столь близко, впервые бакалавр осознал, сколь хрупка человеческая жизнь."}),(0,i.jsx)(s.p,{children:"Две недели после инцидента в кабаке стали для бакалавра периодом катарсиса, уныние царствовало в его разуме – учеба, дальнейшее продвижение, окончание университета, все в одно мгновение потеряла смысл. Если смерть может столь незаметно подкрасться, в любой момент, сжав искру жизни в костлявых ладонях какой смысл в развитии, какой смысл в достижениях, какой смысл в существовании? Если господь так просто взывает к себе души независимо от праведности и греха, какой смысл быть? Эти вопросы мучили Иеронима, что оказался прежней тень самого себя, обучаясь механически, игнорируя приемы пищи, существуя, следуя позывам выработавшейся привычки, в не паттерна бездейственно сидя с пустым взглядом. Неизвестно сколько времени бы ушло у Анагносту, дабы прейти в себя самостоятельно и получилось ли в таком случае удержать собственное место в университете. Но благо Жармен Трюдо не забывал своего друга раз в несколько дней, приходя проведать его, принося новые сплетни или читая для него литературу, пытаясь вырвать из паутины акадии. Средь многих текстов строчки о «панацеи» вернули глазам юноши прошлый блеск, Иероним нашел область, где стоит искать решение своего катарсиса: алхимия и медицина."}),(0,i.jsx)(s.p,{children:"13 июня 1546 года Иероним Анагносту после блистательного публичного диспута получил степень магистра искусств, открывая себе путь к высшим факультетам Падуанского университета. Выбор в пользу медицинского после инцидента в трактире и последующего озарения в момент катарсиса был очевиден."}),(0,i.jsx)(s.p,{children:"Каждое решение имеет свои последствия: в мае 1547 года Анагносту вступает в конфронтацию со своим дедом по материнской линии. Патриарх рода оказался недоволен выбором Иеронима, требуя сменить факультет на более «практичный» и «соответствующий» причастному к родословной Дандоло вместе с тем в случае отказа грозя лишить протекции, а с ней финансирования. Текущий магистр искусств на угрозы ответил письмом с холодным отказом подчинения воле деда."}),(0,i.jsx)(s.p,{children:"В свою очередь ровно два месяца спустя подобное действие несет за собой письмо с единственной фразой: «Убожество». На этом их переписка официально завершилась, как и поступление средств на существование. На истлевших останках было восхищения осталось лишь презрение."}),(0,i.jsx)(s.p,{children:"К собственному удивлению Иероним не столкнулся с проблемой обнищания: финансовая поддержка, полученная за предыдущее года в течение 7 лет, нашлась слишком щедрой для скромных, как оказалось запросов Анагносту, сольдо скопилось достаточно, чтобы продержаться на плаву еще несколько месяцев. К тому же в бесконечной рутине учебы медицинского студенчества будущий Господин Калейдоскоп часто забывал о приеме пищи, что несколько сократило расход, хоть ценой выступающий вперед ребер и легким налетом нездоровой бледности."}),(0,i.jsx)(s.p,{children:"Впрочем, совсем уже спустя три месяца поздним вечером 10 сентября Анагносту получил письмо с печатью рода Дандоло, патриарх рода решил возобновить нарушенные взаимоотношения, ибо спустя столь большой промежуток времени достаточный, дабы успокоить предыдущий гнев, властный старик понял, что затратил слишком много средств и времени, чтобы так просто бросить свою «инвестицию». О восстановлении прежних семейных отношений не могло идти и речи, с другой стороны ни один из двоих не желал подобного."}),(0,i.jsx)(s.p,{children:"24 ноября 1549 года Иероним впервые за 10 лет покидает стены Падуи, с целью отправиться в родную Венецию следуя настойчивой просьбе своего деда по материнской линии, коей возжелал присутствие своего внука в момент рождения правнука, что, в конце концов, унаследует несметные богатства рода Донтоло. Первоначально Анагносту не планировал задерживать в родном городе больше одного дня, ибо его прибытие всего лишь шаг к деэскалации возможного столкновения с патриархом рода. Дети, особенно в столь юном возрасте лишь раздражали будущего Господина Калейдоскопа: капризные, чрезмерно громкие, грязные – разве можно любить подобную мерзость? Непременно нет. Но Ираклий, именно так был наречен младенец, был совершенно другим: спокойным, тихим, с очаровательным взглядом завораживающих небесно-голубых глаз, прекрасным до боли в глазах – он казался внеземным. Иероним Анагносту был в восторге от племянника, настолько, что большую часть времени не отходил от него, в радости кружа вокруг люльки и покинув Венецию лишь спустя 5 дней, последним из всех."}),(0,i.jsx)(s.p,{children:"В 1553 году Анагносту успешно завершает свое обучение на медицинском факультете, стены ставшего за десятилетие уже родным Падуанского университета он покидает совершенно другим человеком: года сгладили его высокомерие, вызванное юношеским максимализмом, желание распустить сплетни обратилось в желание их простого обсуждения, составление теорий на их основе. Копящееся внутри раздражение ныне редко вытекало в холодный гнев, растворяясь в бескрайнем потоке планов, было стремление обособиться и склонность к нелюдимости значительно притупилось под долгим контактом с Жарменом Трюдо."}),(0,i.jsx)(s.p,{children:"Спустя день после окончания своего обучения Иероним по воле патриарха рода Донтоло отправляется обратно в Венецию, дабы занять место личного лекаря при поместье своего деда по материнской линии. Не самая желанная судьба для Анагносту, желающему продолжить обучение, а не разбираться с больными, но противиться желанию члена Большого совета вместе с тем одного из самых влиятельных людей во всей Венецианской республики попросту глупо."}),(0,i.jsx)(s.p,{children:"В услужении при поместье будущий Господин Калейдоскоп пробыл чуть больше 2 лет, прежде чем 13 января 1556 года смерть наконец-то не сомкнула свои костлявые ладони на горле патриарха рода Донтоло, забрав излишне долго цеплявшегося за жизнь старика. Этот день стал небольшим праздником для Иеронима, моментом свободы дальнейшего пути и гибели глубоко презираемого человека, момент который мог быть отложен еще на несколько месяцев, а может быть лет, если бы Анагносту пытался лечить, однако он предпочел, лишь сглаживать симптомы. Лекарь до самого конца мстительно помнил отвержения своего выбора дедом, последующее изменение решения ничуть не сгладило этот факт, лишь усугубило, а ретроспектива с более зрелого возраста на свое детство лишь подпитывала негативные чувства. Ибо теперь отчетливо понимал, что для уже бывшего патриарха рода, его мать, он сам, его отец были лишь инструментами довольства эго. Вслед за этим событие наследник всего богатства рода Донтоло, единственный из потомков имеющий права сохранить за собой сие фамилию, двоюродный брат Иеронима – Лоренцо Донтоло перебирается со своей семьей в поместье, Анагносту здесь более нет места."}),(0,i.jsx)(s.p,{children:"Потратив два дня на сборы, большее время которых ушла на пестование горячо любимого племянника, врач отправляется в двадцатидневное путешествие, пересекая границу родной страны держа путь во Французское королевство град Монпелье в одноименный университет. Коей быть может, потерял былой престиж с закрытие теологического факультета, но разгорелся, подобно маяку для всех жаждущих изучить искусство врачевания. В стенах данного учебного заведения Анагносту погрузился в изучение давно манящий его, жаждущий знаний разум ятрохимии – ртутно-серная теория, основы учений Парацельса, искусство спагирии. Вместе с тем Иероним не спешил определять себя парацельсистом, предпочитая взамен этого занять центральную позицию в алхимическом способе изготовления лекарств, используя знания о «галеновских препаратах» полученные в стенах родного университета."}),(0,i.jsx)(s.p,{children:"В Монпелье Анагносту пребывает до ноября 1557 года, прежде чем, желая оточить навыки врачевания, вместе с тем проверить собственные теоретические знания на практике совместно с рекрутским отрядом отправляется во Фландию, где разгорелся основной театр пятой итальянской войны. Закаленный временем, более не впадающий в катарсис от вида чужой смерти, хранящий в голове знания нескольких медицинских учений, Иероним быстро взял бразды правления над «балом» творящимся в полевом госпитале. Спасение смешивалось с отчаянием и агонией: будущий господин Калейдоскоп холодной непреклонностью боролся за жизнь каждого раненного не зависимо от того насколько безнадежным он был, раз за разом смерть отступала, но за чудесное спасение солдаты расплачивались тяжело изуродованным, убогими телами. Какая жизнь ждет мужчину без руки или ноги, неспособного на полноценную физическую активность? Смерть зачастую оказывалось желанной, но Иеронима не волновало, что будет позже, лишь происходящее на операционном столе. Мольбы о гибели вызывали лишь раздражение."}),(0,i.jsx)(s.p,{children:"На фронте Иероним Анагносту пробыл до самого окончания войны 1559 года огласившего победу Французского королевства, за все эти два года ему дважды пришлось спешно сбегать, дабы не попасть в гущу сражения нагрянувшего в тыл разбитой армии. Как итог столкновение двух держав стоило Иерониму двух маляров выбитых чересчур брыкливыми пациентами во время ампутации, тонкому шраму, на спине полученному от шального удара во время отступления госпиталя, а также несуразный рубец, нанесенный резекцией инфицированной плоти после изъятие пули."}),(0,i.jsx)(s.p,{children:"После войны Анагносту возвращается обратно в Венецию, где до 1561 года пребывает в Ospedale degl'Incurabili на должности лекаря, экспериментируя с концентратами различных соединений растений и металлов в тщетных попытках найти лекарство от сифилиса. Экстракты растительного происхождения не дали значимого эффекта; ртуть, висмут и мышьяк лишь незначительно облегчали симптомы, отчаявшись под конец зимы Иероним, в меланхолии покидает госпиталь."}),(0,i.jsx)(s.p,{children:"К раннему утру 16 марта 1561 года Анагносту спустя множество лет оказывается в Падуе, вновь прибывая к стенам родного университета, чтобы занять пост преподавателя медицинского факультета одновременно с этим принимая решение наконец-то остепенившись, завершив погоню за знаниями и новым опытом. В роли наставника Иероним оказывается крайне щепетильным и особо требовательным в избирании студентов, но те из них кто тяжким трудом иль природным талантом могли соответствовать поставленным критериям, оказывались, окружены чуть ли не отеческой заботой о благополучии и образовании, получая надежную опору для беспрепятственного дальнейшего обучения."}),(0,i.jsx)(s.p,{children:"В 1565 году 6 мая Иероним желая навестить племянника, отлучается из Падуанского университета в Венецию – это решение становиться решающим в судьбе Анагносту. Прибывая в саду вблизи поместья, будущий Господин Калейдоскоп застает Ираклия, целующегося с другим юношей. Мир Иеронима Анагносту раскалывается: глубоко отвращение к творящейся содомии сменяется нарастающей яростью к незнакомцу, как смеет он соблазнять его милого племянника на грех? Как смеет осквернять его, приближая к мерзкой болезни плоти поразившей когда-то его отца?! Лекарю потребовалась вся его сила воли, дабы в этот же миг не прервать сие богомерзкое деяние попыткой убить мерзкого содомита."}),(0,i.jsx)(s.p,{children:"Два дня спустя именно это Анагносту и попытался осуществить исполненные гневом мысли в жизнь: лекарь подстерег любовника своего племянника, предприняв попытку заколоть его хирургическими ножницами, единственное, что спасло юношу внезапное появление Ираклия, коей защитил своего возлюбленного от холодной ярости дяди. После этого происшествия Иероним в апатии покинул Венецию, вернувшись в Падую; любовь к племяннику сходилась с отвращением. Три месяца будущий Господин Калейдоскоп прибывал в глубоких раздумьях смешанных с перепадами разъедающего уныния, прежде чем принять окончательное решение - 22 августа Ираклия получает письмо содержащие сдержанные извинения и клятву сохранить тайну, искренняя любовь к племяннику оказалась сильнее всего остального."}),(0,i.jsx)(s.p,{children:"24 ноября 1568 года лекарь вновь отправляется в Венецию, получив приглашение от племянника на банкет в честь его день рождения. По иронии судьбы именно в этот радостный день Анагносту пришлось нарушить клятву Гиппократа, обагрив свои руки в крови: прогуливаясь по малолюдному месту сада поместья, Иероним застал одного из приглашенных гостей в шоке наблюдающим за Ираклием и его любовником. Будущий Господин Калейдоскоп действовал инстинктивно, секунда, невольный свидетель, хрипя, упал на землю с воткнутыми в глотку ножницами. Распрощавшись с племянником и получив от него последний подарок – небольшую безделушку в виде распустившийся розы взамен даруя свое благословение на отношения, Анагносту сбегает из Венецианской республики."}),(0,i.jsx)(s.p,{children:"Пробыв четыре месяца на корабле, Иероним прибывает к берегам Альбиона, где подталкиваемый чувством вины за убийство останавливается в небольшом прибрежном монастыре постригаясь в монахи. В обители душевные терзания достигают своего апогея, выражаясь в мучительных кошмарах вместе с растущим чувством бессмысленности собственного существования и собственных деяний. Уже зимой 1569 года столь же внезапно одновременно с тем волнообразно чувство вины сменяется постепенно растущей уверенности в собственной невиновности, все чаще Анагносту посещают мысли о том, что жертва сама виновата в своей смерти. Наконец-то с первым месяцем весны Иероним более испытывая не раскаяние, а раздражение и презрение к убитому с чувством удовлетворения собственным поступком сбегает из монастыря, найдя новое пристанище в деревушке расположенной в двух днях пешего пути от храма."}),(0,i.jsx)(s.p,{children:"Иероним достаточно быстро интегрировался в общество деревенских жителей, заработав всеобщую симпатию благодаря отточенным многолетним опытом врачебным навыкам и добродушием, смешанным с галантностью за которыми зачастую скрывалось презрение вместе с раздражением. Вместе с тем в глубине души Анагносту начали пробуждаться старые привычки: ему вновь до скрежета зубов желалось узнать что-то новое, подкрепить существующую систему знаний новой практикой, новым учением. Тринадцатого февраля 1571 года стала днем, когда терпение лекаря треснуло, и Иероним Анагносту воспользовавшись алчностью сына престарелого могильщика начал скупать у него трупы, дабы в дальнейшем заняться их препарированием. Впервые в жизни у Иеронима был столь свободный доступ к такому количеству материала, его восторгу не было предела."}),(0,i.jsx)(s.p,{children:"Именно это решение стало фатальным для будущего Господина Калейдоскопа – поздним вечером 25 октября, когда ночь накрыла землю, деревенский охотник возвращающийся домой куда позднее обычного изобличил сына могильщика, коей под давлением мужчины трусливо выдал своего нанимателя, свалив всю вину на него и приписав еще десяток грехов. Разъяренные разграблением могил их родственников и предков деревенские жители с вилами, а также сверкающими в ночи факелами шествовали к дому Иеронима. Разбуженный среди ночи, лекарь в панике успел забаррикадировать дверь, вместе с тем сумев тяжело ранить одного из пришедших нанеся удар пилой для ампутации, после чего совершив еще несколько попыток прорваться, получив в итоге лишь больше раненных, один из деревенских жителей решил поджечь дом."}),(0,i.jsx)(s.p,{children:'Окруженный в горящем доме стремительно заполняющимся едким дымом будущий Господин Калейдоскоп, исполненный лютой ненавистью, исторгал одно проклятье за другим, перекрикивая шум разгорающегося пламени — "Пусть мучительная смерть настигнет каждого из вас! Путь холодная зима оставит вас без посевов, и вы все сдохните от мучительного голода, как и положено грязным животным! Я проклинаю каждого до единого! Без меня ваших детей будет рвать кровью, трясти от лихорадки, они будут гнить изнутри, ибо никто не сможет вылечить болезнь! И я буду хохотать, смотря на это из гиены огненной, где в конечно итоге вы все окажитесь!". В конечном итоге Иероним не желая мучительно сгореть заживо в порыве приступа безысходности смешанным с безумством, вспарывает себе глотку теми же хирургическими ножницами, которыми было совершенно его первое убийство. Иронично.'})]})}),(0,i.jsx)(r,{title:"Жизнь в Энкраже",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Первой эмоцией возникшей в разуме Иеронима после того как в 1574 году Врата Башни извергли его наружу стала недоумение – окружающие пространство совершенно не подходило под описание ада изложенного в «Божественной комедии» Данте Алигьери, остальные менее популярные трактовки загробного мира сохранившиеся в памяти Анагносту также не обладали хоть какой либо актуальностью. Минуты в задумчивости неспешно сменили былое недоумение на сдержанную заинтересованность, в особенности изменениями, произошедшими с собственным телом."}),(0,i.jsx)(s.p,{children:"Буквально через несколько часов после появления Иероним Анагносту встречает сестру по греху, что заботливо, правда, без углубленных разъяснений объясняя лишь базовые вещи, безопасной дорогой провела новоприбывшего, восхищающегося буквально всему грешника прямиком к месту расположения общины сирен. Где Анагносту с распростертыми объятьями приняли его новые сестры и находящиеся в куда меньшее количество братья."}),(0,i.jsx)(s.p,{children:"Впоследствии некоторого времени с момента прибытия в общество сирен Иероним, только начинающий углубляться в азы существования Энкража, вместе с еще несколькими недавно прибывшими сестрами принимает участие в ритуале Резонанса души, цель которого определить принадлежность новорожденной русалки к одному из рода Живых Драгоценностей. Как итог – Анагносту, чей резонанс эссенции в отличие от остальных морских дев из-за своей странной нечеткости с трудом был определен, предстояло пень в унисон с родом Уз Амфитриты, что воспевал единство."}),(0,i.jsx)(s.p,{children:"В конце того же 1574 года для Иеронима Анагносту, как части единой песни Уз Амфитриты, наступает важный день – день обряда единения со своим родом, принятие частицы Рифа, как фрагмента своего собственного существования ради достижения истинной гармонии в коллективном хоре. Для многих обряд стал торжеством, завершением собственной целостности, для Анагносту разочарованием: симбионт вызывал лишь безразличие, смешанное с легким уколом сомнения, несомненно, эссенция не отвергала новый фрагмент собственной сущности, но также не принимало его."}),(0,i.jsx)(s.p,{children:"Десять лет спустя в 1584 году внутренний диссонанс Иеронима достиг критической точки. Смешавшись с копившимся годами ядовитым раздражением, он разгорелся в холодное пламя ярости: гармоничное единство было лишь красивым, но пустым саваном, скрывающим гниющий труп высокомерного лицемерия. Пресловутые узы лишь оковы, запершие в иллюзорном пути общего процветания, а Риф их материальное отражение – столкнувшись с приговором, вынесенным собственным разумом, Анагносту совершил один из самых необдуманных поступков за все свое существование. Подобно тому, как при жизни он врачевал наросты, раскаленный металл оказался вдавленным в коралл, оставляя на его поверхности чудовищные шрамы, однако тот день не стал мгновение, когда была поставлена точка. Агония прижигания погасила бурлящий гнев, породив сомнения достаточные, дабы затуманенный болью разум дрогнул, отрекаясь довести совершенное деяние до конца."}),(0,i.jsx)(s.p,{children:"Последующие 30 лет существования в загробной жизни вплоть до 1618 года Иероним Анагносту неспешно постигал культуру общую культуру своей новой расы и частные обычая каждого из родов Живых Драгоценностей, одновременно с тем периодически путешествуя к Замку в составе дипломатических делегаций, чтобы посетить Библиотеку. Коя быстро стала одним из самых любимых мест молодого грешника, что впитывал знания, словно губка воду, именно книжные богатства библиотеки в момент первого её посещения в 1594 году воодушевили Иеронима активно приступить к изучению собственной магии. С другой стороны погрузившись в глубокий омут новой информации, Анагносту заметно отдалился от своих братьев и сестер, предпочитая потратить время на познания чего-то нового, чем наладить контакты с родом, уродливый шрам, растекшийся по симбионту – символу единства рода только подчеркнул избранную отрешенность. Длительные попытки идентифицировать собственное колдовство в окружении одиночества лишь усугубило нарастающий разрыв."}),(0,i.jsx)(s.p,{children:"В 1619 году будущий Господин Калейдоскоп наконец-то полностью осознает принцип работы собственной магии, так удивительно роднясь с силой сгинувшего в противостоянии Сестер рода сирен, значительно расширяя свой арсенал по сравнению со сверстниками вместе с тем наголову обходя в мастерстве. За подобное ему пришлось расплатиться отстраненным отношением с собственным родом, он был подобен случайному уродливому мазку чернил на пестрящей цветами картине. Кроме того отросток Живого Рифа, отличительная особенность рода Уз Амфитриты, символ части целого, на теле Анагносту со временем истекающим быстрее с каждым использованием магии - истончился, обволокся кристаллическим налетом, покрылся множеством трещин. Собственная сила отвергала дар избранного ритуалом рода. В конце концов, изуродованный в давно минувшем припадке ярости симбионт буквально разошелся по черным полосам шрамов в один момент, разорвавшись подобно гнилому фрукту исторгнув наружу внутреннее содержимое. Боль была по-настоящему мучительной, но с агонией пришло освобождение – такт эссенции стал четким как никогда прежде."}),(0,i.jsx)(s.p,{children:"Отвержение частицы Рифа сыграло ключевую роль в судьбе Иеронима вскрыв путь ранее непостижимый для него – в один из дней того же 1619 года мужчина после возвращения на территорию рода в непривычном для себя порыве рожденном внезапно обострившимся предчувствием отклонился от привычного маршрута. Он ведомый едва ощутимым отзвуком собственной эссенции, чьей лейтмотив с каждым шагом становился все отчетливей, обнаружил место столь притягательное для внутреннего естества - давно заброшенный, но не потерявший своего таинственного великолепия чертог Обсидиана, Дворец Стеклянных Глаз. Иероним не стал первопроходцем, спустя эоны вновь открывшим сию область для Хора, ибо знания о существование Дворца и важнее его месторасположение никогда не считались потерянными, с другой стороны общество сирен утопающее в проблемах новых эпох было безразлична к проклятому непостижимому наследию исчезнувшего рода. Средь пустынных зеркальных галерей, тлетворного беззвучного шепота порожденного магией мрака и полубезумных бормотаний поглощенных, Анагносту впервые за долгое время ощутил чувство родства."}),(0,i.jsx)(s.p,{children:"Нарастающая безразличность во взаимоотношениях, гротескная гибель симбионта Живого Рифа, ощущение испытанные в Дворце Стеклянных Глаз, а также взаимное не понимание мировоззрения вместе с отторжением идеалов Уз Амфитриты подтолкнула Иеронима в 1620 году провести повторный ритуал Резонанса души. Дабы в более зрелом состоянии выявить род, в полной мере гармонирующий с идеологией Анагносту, в конце концов, результат первой церемонии был достаточно смутен для точной трактовки. На этот раз резонанс заиграл во всей своей красе - вторя извечному вопросу рефлексии собственного «я», ужасу гибели, очарованию нового мира застывшему во взоре Седны; произошло истинное чудо: один из родов Утраченных Драгоценностей, трагически сгинувший Отблеск Нарцисса, вновь вернулся в этот мир. Дворец Стеклянных Глаз наконец-то обрел своего полноправного хозяина."}),(0,i.jsx)(s.p,{children:"Возрождение рода историческое событие для всего народа сирен, существенно не отразилась на бытие Иеронима, несомненно, более он не был обычным представителем своей расы – с момента окончания ритуала за ним закрепилось позиция «Единственного Зеркала», владыки своего рода. Но Анагносту был еще слишком юным грешником для полной власти, заключающейся в этом титуле, к тому же, Отблеск Нарцисса может и был возрожден, пока состоял лишь из одного существа. Потому будущий Господин Калейдоскоп до сих пор находился на попечении Уз Амфитриты, хоть теперь отношения с сестрами и братьями этой Живой Драгоценности стабилизировались, ибо их подход во взаимодействии, с открывшимися новыми переменными, претерпел изменения – он более не был дисгармоничной мелодией, теперь он музыка совершенного другого идеала."}),(0,i.jsx)(s.p,{children:"С начала 1621 года Иероним начинает все чаще покидать общину сирен, самостоятельно прокладывая новые маршруты до Замка, используя его как отправную точку для дальнейших путешествий по территориям Энкража с низкой концентрацией проклятой энергией. Вышеуказанные факторы побуждают Анагносту, не утратившего не капли восхищения окружающей реальности, начать вести кропотливые записи о найденных представителях фауны, флоры и необычных материалах загробного мира; в дальнейшим сверяя полученную информацию с исследованиями ученых Научной Ассоциации."}),(0,i.jsx)(s.p,{children:"В 1622 году Иероним Анагносту находит знакомое со времен своей жизни, но вместе с тем отличное от земной вариации увлечение – алхимию, с головой погружаясь в изучение сие области. Атрибутная система Соломона с первого изучения влюбила в себя будущего Господина Калейдоскопа, побудив последнего, предварительно выучив практически дословно реестр разрешенных для сбора растений и охоты животных, разбавить свои небольшие вылазки сбором материала для создания синтагм. Первоначальное увлечение превратилось в профессиональную сферу деятельности."}),(0,i.jsx)(s.p,{children:"В конце 1629 года род Отблеск Нарцисса пополняется новым дитем, ставшим за долгое время второй сиреной резонирующей с обсидианом, чье обучение основам, царящим в загробном мире, лично взял на себя Единственное Зеркало. Новая сестра в мгновение была окружена странным подобием отечественной заботы, одновременно с тем в первое же время вовлечена в путешествия и алхимические исследования. Правда, спустя относительно короткое время Иероним осознал, насколько чрезмерно насыщенным оказался поток новой информации, обрушившийся на грешницу, вследствие чего доверил её дальнейшие развитие покровительству Скорби Фетиды."}),(0,i.jsx)(s.p,{children:"Незадолго до середины 1630 года ознаменовала вступление Анагносту в лоно Научной Ассоциации Энкража на должности младшего эдитерона, произошедшее по приглашению одного из старших эдитеронов из рода Уз Амфитриты состоящего в Секторе Артефактной Экспертизы, после блистательно успешной защиты итоговой диссертации «Исследования свойств эклипсита. Прикладное использование» перед Конкорсиумом. Отделом, за которым оказался, закреплен будущий Господин Калейдоскоп, предсказуемо стал Сектор Алхимической Конденсации «Соломон»."}),(0,i.jsx)(s.p,{children:"В 1632 году алхимик переживает День Черного Солнца на территории Дворца Стеклянных Глаз в тщетных попытках защитить родные просторы от губительного кровавого дождя, объединяет собственную магию с искусством алхимии, ткет экспериментальное защитное заклятье. Колдовская защита держится ровно две минуты, прежде чем рухнуть под градом концентрированной проклятой энергии; сил повторить ритуал у Иеронима не остается. Катастрофа навсегда останется в памяти Анагносту, найдя отражение на его теле и сломав судьбу его подопечной изуродовав её ЭПФО."}),(0,i.jsx)(s.p,{children:"В 1637 году Иероним Анагносту уже известный многим своим коллегам как Ткач Отражений совместно с членами вальгардов участвует в процессе восстановления экосистемы от последствий Дня Черного Солнца и последующей за ним разгоревшейся засухи. Единственное Зеркало в День Черной Луны пытается использовать целительную силу белоснежного дождя аномалии «Плачущая Луна» в алхимическом преобразовании для сотворения синтагмы способной стабилизировать течение проклятой энергии. Эксперименты оказались провальными, сила аномалии не поддается контролю, быстро выветриваясь, лишь соединение с атрибутами воды и космоса позволяет сохранить неимоверно малую частицу очищающей силы, совершенно бесполезную в данной ситуации."}),(0,i.jsx)(s.p,{children:"1665 год становиться временем, когда Ткач Отражений за заслуги перед НАЭ и составления объемной трилогии пособий по алхимическому искусству получает повышение, вступая в должность старшего эдитерона. Получив новые полномочия, Иероним практически сразу же преступает к формированию нескольких проектов, среди которых присутствуют, как одиночные исследования, так и совместные разработки с другими отделами сформированной командой."}),(0,i.jsx)(s.p,{children:"В 1669 году Анагносту завершает антологию исследовательских работ: «Фундаментальное изучение свойств эклипсита. Реакция ингибирования в алхимической реакции»; «Сложные синтагмы. Профессиональная алхимия», коя спустя два года горячих споров с Верховным Арбитром того времени Готфрид ван дер Зее, множественным отказам и редакциям, наконец-то выходит в свет."}),(0,i.jsx)(s.p,{children:"В период 1673 по 1690 год Ткач Отражений многие часы проводит в архиве Научной Ассоциации, а также несметной библиотеке Замка анализируя множество работ алхимиков-изобретателей предыдущих веков предпринимавших попытку создать устройство для точного определения атрибутов материала и тонкого наблюдения за реакцией. На основе полученной компиляции исследований, а также личного опыта в использовании эклипсита Иероним Анагносту приступает к конструированию собственного аппарата. В общей сумме было создано около 4 прототипов имеющие те или иные дефекты, прежде чем Oculus Essentiae в простонародье закрепивший обозначение «Адуляра» был готов к эксплуатации. Данное устройство было столь инновационным и желанным в научном сообществе, что даже царящий в то время мучительный бюрократический ад не смог остановить начало стремительного использования «Адуляров»."}),(0,i.jsx)(s.p,{children:"С 1694 года по 1719 год Иероним вместе с действующим Архивариусом Современности Салазаром Фейнманом приступает к совместной лабораторной работе, выступая в роли консультанта по вопросам, касающимся сферы атрибутной системы Соломона, а также алхимии, в том числе процессах многоэтапного создания сложных синтагм. Одновременно с этим старший коллега в приятных беседах между рабочим процессом делиться с Анагносту опытным взглядом на внутреннее организационное устройство НАЭ."}),(0,i.jsx)(s.p,{children:"1700 год знаменуется одновременно двумя значимыми событиями в существовании Единственного Зеркала: в начале года грешник уныния совместно с Хартии Прикладных Материй представляет научному сообществу Индуктор Контролированного Распада, он же Сосуд Разложения или сокращенно ИКР – устройство, направленное на выделение атрибутной энергии в чистом виде из различных органических и неорганических материалов. Хоть устройство не получает особое распространение из-за запрета массового производства со стороны Готфрид ван дер Зее, резонанс вызванный данным устройством, а также предыдущими изобретениями, исследованиями в области системы атрибутов Саламона и расположение со стороны Архивариуса Современности приводит к назначению Иеронима Анагносту на должность Эвритария Сектора Алхимической Конденсации «Соломон». Одновременно с тем он получает за собой прозвище «Господин Калейдоскоп»."}),(0,i.jsx)(s.p,{children:'В 1723 году Анагносту на некоторое время отстраняется от научной деятельности, решив в полной мере заняться организацией собственного рода, к тому же был весьма весомый повод – за долгое время по результатам ритуала Резонанса души сразу 3 сирены оказались близки к Отблеску Нарцисса. Наблюдать за тем, как новорожденные грешники с удивлением исследуют окружающий мир, было по-настоящему волнующим зрелищем для Ткача Отражений, который придавался воспоминаниям о начале своего пути. Вместе с тем вспоминая старые заметки, оставленные им на одной из ботанических зарисовок: «Судьба так иронична: общество сирен с единым резонансом называют родом, термином, подразумевающим под собой семейную принадлежность, по-настоящему близких людей, передачу сакральных знаний предыдущего поколения новому. Но в моем случае я оказался окружен "детьми- самоучками", подобно беспризорникам сбившимися в кучу лишь ради выживания, что говорить о раскрытии расколотого проклятьем наследии? К тому же, нас слишком мало, максимум кучка, а не род. Лишенные прошлого и, вероятно, будущего. Впрочем, все в руках Темных Предков, время покажет, какое падение иль возвышение ждет Отблеск Нарцисса в конце».'}),(0,i.jsx)(s.p,{children:"Однако в отличие от второй по старшинству сирены, отозвавшейся на резонанс Отблеска Нарцисса, Иероним на этот раз держится на расстоянии, не проявляя особой привязанности или симпатии. Лимит эмпатии закончился при обучении сирены пришедшей второй после него, на этот раз в новых отсветах он видел лишь раздражающих невежд, не способных осознать даже четверть резонанса вопрошающего ужаса Седны."}),(0,i.jsx)(s.p,{children:"1749 в День Черной Луны Иероним спустя долгое время размышлений и медитаций решился провести созданный им же ритуал, проистекающий из обрядов течения Темной Матери, чей целью было попытка развеять проклятье Мрака Эннеады гнилостным пятном растекшаяся по истории Отблеска Нарцисса. Сила Отблеска Фатума, облаченная в «кокон» Среднего Квеллария слилась с искусством алхимии, зеркала отразили мягкий свет луны, свиваясь в единый луч, взывая к очищающему могуществу слез Матери. На несколько часов влияние губительной магии Мрака и вправду удается ослабить, давая призрачную надежду ухватиться за знания прошлого, но искажающий истину мрак вернулся раньше, чем удалось расшифровать хоть что-то."}),(0,i.jsx)(s.p,{children:"В 1766 Иероним Анагносту инициировал первый в истории возродившегося рода ритуал «Безмолвного Собрания». Крайне специфичный опыт, оставивший Ткача Отражений на некоторое время в состоянии глубокой задумчивости, переросшей в разгорающееся желание восстановить как можно больше традиций и обрядов прошлого."}),(0,i.jsx)(s.p,{children:"К 1768 году несколько из младших сирен родов Уз Амфитриты и Отблеска Нарцисса получают приглашение вступления от Анагносту в Научную Ассоциацию, он лично берет руководство над грешниками заинтересовавшимися алхимией, распределяя остальных между своими близкими знакомыми. Формируется надежная основа проверенных подопечных для организации исследований в условиях абсурдно ужесточающихся действующим Верховным Арбитром правил."}),(0,i.jsx)(s.p,{children:"В начале 1774 года случилось неожиданное – в результате несчастного случая, вынудившего Готфрида ван дер Зее лично прибыть на дело, он находит свою окончательную смерть. Причиной этого послужило сразу несколько факторов: чрезмерная громоздкость бюрократического аппарата созданного погибшим Верховным арбитром, личная неприязнь звеньев различного положения к последнему, значительные пробелы в технике безопасности работы с аномалиями или гнозисами, их неактуальность, долгое реагирование на возникновение проблемы, приведшей к её усугублению в чрезвычайную ситуацию. А также по неподтвержденным слухам сознательное халатное отношение к формированию выездной группы и преднамеренное искажение гнозиса."}),(0,i.jsx)(s.p,{children:"В том же 1774 году Иероним Анагносту выдвигает свою кандидатуру в предстоящих выборах Верховного Арбитра. Обладая безупречной репутацией, значительным научным авторитетом, известной преданностью идеалам Ассоциации, позицией обещающей наконец-то вырваться из длительной стагнации, а также поддержкой сразу двух Архивариусов, и вдобавок получивший большинства голосов Эвритариев – Господин Калейдоскоп без особой конкуренции вступает на высшую должность Научной Ассоциации Энкража."}),(0,i.jsx)(s.p,{children:"1775 год становиться годом перемен для Научной Ассоциации: значительная часть заброшенных при прошлом Верховном арбитре исследований были возобновлены и получили финансирование, была оформлена новая резолюция касающаяся официальной позиции Ассоциации в отношении инцидента Братства Крови и Скептиков Пятидесяти, пересмотрены внутренние отношения с синклитами представленными Черным Рынком, в совместной работе с представителями Анмемарей обновлены протоколы безопасности касающиеся работы с гнозисами, начато массовое производство полевых и стационарных ИКР."}),(0,i.jsx)(s.p,{children:"В 1797 году Господин Калейдоскоп проектирует модификацию Oculus Essentiae, увеличивая количество зеркал, дополняя конструкцию специальным «информационным фильтром», в завершение, накладывая дополнительный поверхностный каркасный контур играющего роль стабилизатора. Полученная усовершенствованная версия удостаивается название «Жемчужный Лабиринт» и производиться всего в восьми экземплярах, позволяющих проводить хирургически точные манипуляции с атрибутами системы Соломона, в полной мере контролируя проходящие алхимические реакции с отсутствие какой-либо даже незначительной погрешности."}),(0,i.jsx)(s.p,{children:"1812 год стал временем, когда Иероним Анагносту властью Арбитра и Единственного Зеркала объявил о переходе Дворца Стеклянных Глаз расположившегося недалеко от Бастиона на скалистом берегу восточной части Моря Кровавых Слез под юрисдикцию Научной Ассоциации. Обитель рода Отблеска Нарцисса стала второй резиденцией Ткача Отражения вместе с тем объектом жарких споров между остальными частями Хора, кои закончились глухим ропотом Клинка Митры и Смеха Лиссона. Последние могли устраивать кровавый террор в море и упиваться своей анархичной свободой, обрывая драгоценные жизни исследователей Ассоциации, но вступать в конфронтацию в самом сердце территории другого рода – игра не стоящая свеч. Персонал данного объекта практически на 2/3 был представлен сиренами, большинство из которых не являлись полноценными участниками НАЭ, а добровольцами общины, рекрутированными согласно договору между Ткачом Отражений и главами других родов Живых Драгоценностей, в основном Узами Амфитриты, а также Скорби Фетиды. Оставшееся меньшинство включило в себя келпи вместе с небольшими группками представителей других рас. Исследовательский Комплекс взял на себя сразу две роли: перевалочного пункта в добыче эклипсита, чье место добычи располагалось в ближайшем горном массиве, а также «сада» где светлые умы Энкража планировали с помощью вод с высокой концентрацией проклятой энергии попытаться взрастить Кристалл Энергии."}),(0,i.jsx)(s.p,{children:"В 1869 году Дворец Стеклянный Глаз оказался на грани уничтожения: во время Морской Угрозы возросшей из аномалии «Забытой Тиши» помимо стремительно наступающего прилива сдерживаемого монолитными стенами покрытыми отсутствующим атрибутом, вода, изобилующая высококонцентрированной проклятой энергией, гигантским гейзером хлынула из подземной части чертогов. В одно мгновение около двух дюжин грешников, даже не успев осознать угрозы, были поглощены потоком, встретив гибель; лишь благодаря дальнейшему оперативному реагированию и наличию столь обширного множества персонала способного контролировать водную стихию с большим трудом удалось остановить продвижение воды. После чего Верховный Арбитр, лично присутствовавший во время катастрофы в исследовательском комплексе, воспользовавшись реакцией кристаллизации в массивных объемах, истратив большую часть накопленного запаса высоко-рангового атрибутного концентрата, изолировал образовавшийся синтагмой затопленные этажи, дабы затем усилить её наложением рун Среднего Квеллария: «Замок нерушимый непроницаемый»."}),(0,i.jsx)(s.p,{children:"В 1910 году Иероним Анагносту в ходе непродолжительных переговоров инициированных Советом Тринадцати о возможности обмена знаниями и совместной работой над раскрытиями секретов загробного мира, Ковен Небьющегося Сердца был включен в ряды Научной Ассоциации Энкража."}),(0,i.jsx)(s.p,{children:"В начале 2019 года Ткач Отражений на достаточно продолжительное время выпадает из жизни Ассоциации, дабы заняться инспектированием целостности печати наложенной на нижних этажах Дворца Стеклянных Глаз. И провести ритуал её обновления, чтобы подавить в зародыше, даже минимальный шанс дестабилизации и, следовательно, повторного прорыва глубинных вод Моря Кровавых Слез. Подобная предосторожность с учетом текущей целостности барьерной синтагмы была следствием, нарастающим с года беспокойством о возможности повторения катастрофы 1869 года или исполнения более мрачных сценариев и, следовательно, вероятности полной потере одной из ключевых баз Ассоциации – Энкраж не самое спокойное место, никогда не знаешь когда очередной год обратиться в год бедствия. Проводимый ритуал не был инновационным, он фактически веками творился алхимиками хоть возможно и не в форме колдовского таинства проводимого Верховным Арбитром, трансформация Нигредо в Альбедо. Внутренняя поверхность синтагмы оказалась исчерчена алхимическим символом серебра от центра каждого круга, которого расходились множества изломанных линий расходящихся по всему кристаллическому заслону, огибая ранее наложенный квелларий. Впоследствии символ был наполнен расплавом кристаллов Морелия смешанным с чистым атрибутным концентратом золота и космоса. Следующим шагом стало высечение на субстрате четырех квадратных углублений с каждой стороны света, соединенных с прочерченными линиями, дабы заполнить их смесью Ферроцвета и волокон Фиброзема. Конечным шагом всего процесса стал синтез всех компонентов с исходной синтагмой путем воздействия среднего Квеллария, образуя чрезвычайно устойчивую для воздействия проклятой энергии, практически неразрушимую, печать."})]})})]}),(0,i.jsxs)(r,{title:"Дополнительно",children:[(0,i.jsx)(r,{title:"Факты о персонаже",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Жестикуляция",children:(0,i.jsx)(s.p,{children:"Подобно накатывающим приливам излишней театральности Ткач Отражений временами склонен к крайне экспрессивной и богатой жестикуляции, подчеркивая практически каждое свое предложение, а иногда и слово акцентирующим на общем посыле жестом. В большинстве случаев катализатором сей экспрессии становиться разжигаемое чужой некомпетентностью чрезмерное раздражение иль разочарование, придающее едкий саркастический оттенок. И лишь изредка жестикуляция становиться красочным дополнением к нечастым вспышкам восторженности."})}),(0,i.jsx)(h,{title:"Шрамы Дня Черного Солнца",children:(0,i.jsx)(s.p,{children:"Вследствие событий повлеченных Днем Черного Солнца 1632 года поверхностная чувствительность зоны кисти и предплечья правой руки Иеронима Анагносту значительно притупилась, оставшись лишь блеклыми пятнами тактильных ощущений, а кожа этой области «украшена» широкими насыщенно-черными трещинами вместе со сколами, обнажающими окостенелую плоть."})}),(0,i.jsx)(h,{title:"Коллекционер литературы",children:(0,i.jsx)(s.p,{children:"Верховный арбитр отъявленный коллекционер различных литературных собраний: распространенные и известные каждому грешнику произведения; случайные очерки; отклоненные от публикации собственной же дланью работы; ограниченные серии книг, спектр коих может начинаться от настолько неудачных бульварных романов, что собственный автор возжелал их уничтожить до древних фолиантов хранящие запретные знания. Все это находит свое место во все пополняющимся собрание Господина Калейдоскопа."})}),(0,i.jsx)(h,{title:"Карманные часы",children:(0,i.jsx)(s.p,{children:"Постоянно носит с собой аксессуар в виде карманных часов, который, несмотря на свой внешний вид на самом деле исполняет функцию компаса проклятой энергии, ибо часовые стрелки выкованы из сольвиона."})}),(0,i.jsx)(h,{title:"Профессиональный статус",children:(0,i.jsx)(s.p,{children:"Иероним является Верховным Арбитром НАЭ, высшей должностью в Ассоциации. Он также возглавляет род Отблеск Нарцисса в Хоре сирен и владеет Дворцом Стеклянных Глаз."})}),(0,i.jsx)(h,{title:"Отношение к подопечным",children:(0,i.jsx)(s.p,{children:"Ткач Отражений проявляет ярко выраженный фаворитизм по отношению к членам НАЭ, считая их неспособными на серьёзные проступки. Однако при неопровержимых доказательствах вины он проявляет суровость и жестокость в наказаниях."})})]})}),(0,i.jsx)(r,{title:"Внешность",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(s.p,{children:"Относительно высокий, приблизительно 188 сантиметров, не обделенный мышечной массой, но все еще больше соответствующий прилагательному «худощавый» чем «жилистый» или тем более «атлетичный» мужчина, чей вес едва ли переходит границу 69 килограмм. Его волосы - уже давно поседевшие, словно выцветшие кораллы, но сохранившие эластичность вместе с крепость волнистые локоны, спускающиеся равномерными потоками, за исключением одной вечно выбивающейся вперед пряди, вниз обрамляя исчерченное мелкими выразительными морщинами лицо подчеркнутое аккуратной бородой. Говоря о лике Ткача Отражений нельзя молчать о выразительных бордово-коричневых глазах, часто они спокойный штиль, изредка пронзительная отдающая металлическим блеском буря, но всегда в их глубине таиться зловещая пустота. «Знаком» на плоти причисляющим Иеронима к сиренам стала грубая ороговевшая бородавчатая кристаллическая кожа, расползшаяся поверх грудинно-ключично-сосцевидных мышц в большинстве случаев скрытая под воротником, в области лопаток и пространстве меж фалангами. Помимо расовых особенностей кожный покров мужчины покрывает невыразительный звездчатый шрам, расположившийся прямо под адамовым яблоком, прямое отражение причины смерти окруженный татуировкой алхимического символа философского камня. Грудная клетка в свою очередь тоже оказалась украшена татуировкой – древом сефирот, 10 кругов которого взамен привычного названия сфирот представлены названием атрибута на Среднем Квелларие, два оставшихся атрибута «Тьма» и «Морок» кругами вытатуированы на спине."}),(0,i.jsx)(s.p,{children:"Гардероб Господина Калейдоскопа однотипен: всегда это длинная доходящая до середины голени вечно белоснежная шелковая мантия с высоким воротником, украшенная золотым орнаментом, легкие штаны схожего оттенка и мужские туфли с широким каблуком, издающие характерный отчетливый стук при ходьбе, хотя иногда даже в них Арбитр умудряться двигаться совершенно бесшумно. Возможно дело в ограненном эврите интегрированном в конструкцию обуви? Помимо представленной выше одежды на правой руке лидера Ассоциации красуется элегантная черная перчатка, доходящая до надмыщелок плечевой кости скрывая шрамы оставленные катастрофой Дня Черного Солнца, тыльная сторона коей носит символ НАЭ. Левую же руку скромно украшает золотое кольцо нашедшее место на указательном пальце."})]})}),(0,i.jsx)(r,{title:"Навыки и умения",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Подводное дыхание сирен",children:(0,i.jsx)(s.p,{children:"Способность дышать под водой, характерная для всех представителей расы сирен."})}),(0,i.jsx)(h,{title:"Мастер Алхимии",children:(0,i.jsx)(s.p,{children:"Без всяких сомнений в Энкраже мало кто сможет соперничать в искусстве алхимии с Верховным Арбитром Ассоциации, за его плечами практически 4 вековой опыт этом деле, множество научных трудов, часть из которых сформировали нынешнюю программу обучения науки Соломона, многочисленные ученики, заработанный титул, а также изобретения изменившие подход к современной алхимии. От простейших реакций до многоэтапного взаимодействия синтагм между собой нет ни одного раздела незнакомого рукам Иеронима."})}),(0,i.jsx)(h,{title:"Знания Квеллария",children:(0,i.jsx)(s.p,{children:"Как и подобает любому члену Научной Ассоциации, Иероним Анагносту в совершенстве владеет современным квелларием, будь-то использование его в заклинаниях иль в качестве средства общения. Более того Ткач Отражений за многие годы руководства НАЭ на относительно приемлемом уровне изучил средний квелларий научившись использовать его в своих колдовских ритуалах. Даже старый квелларий не остался непознанным жадным разумом Ткача отражений, правда, к его большому сожалению лишь на уровне нескольких простых фраз и распространенных слов."})}),(0,i.jsx)(h,{title:"Ловкость рук",children:(0,i.jsx)(s.p,{children:"С земной жизни до нынешнего века пребывания в Энкраже деятельность Господина Калейдоскопа была всегда связана с тонкой работой руками: терапия, изготовление ятрохимических препаратов, полевая хирургия, алхимия – ни одного года из нескольких столетий жизни не обошлось без развития мелкой моторики, сделав сирену виртуозом в обращении собственных дланей."})}),(0,i.jsx)(h,{title:"Обращение с оружием",children:(0,i.jsx)(s.p,{children:"Господин Калейдоскоп способен управляться стилетом, кинжалами и схожим по типу оружию на уровне чуть лучше неофита, что точно не ранит себя собственным клинком, способен нанести неожиданный удар, прикончит новичка или неосторожного бойца схожего мастерства. Но уж точно долго не продержится в поединке фехтования против опытного солдата, тем более против того, кто посветил свою жизнь владению оружия."})}),(0,i.jsx)(h,{title:"Магия Отблеска Фатума",children:(0,i.jsx)(s.p,{children:"Уникальная магия рода Отблеск Нарцисса, связанная с зеркалами и отражениями. Позволяет создавать зеркальные порталы, отражать атаки и манипулировать восприятием противников."})}),(0,i.jsx)(h,{title:"Языки",children:(0,i.jsx)(s.p,{children:"Владеет итальянским, латынью, французским, испанским, современным и средним квелларием."})})]})}),(0,i.jsx)(r,{title:"Слабости",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Камертон",children:(0,i.jsx)(s.p,{children:"Звуки Камертона причиняют сильную головную боль, мешая сконцентрироваться на использовании заклинаний."})}),(0,i.jsx)(h,{title:"Страх зеркал",children:(0,i.jsx)(s.p,{children:"Подобно прочим представителям собственной расы Иероним избегает собственного отражения в зеркале, ибо видит в нем свое лицо, расколотое, словно маска и обнажающее пустоту – символ страха распада собственного «я», падения в безумие."})}),(0,i.jsx)(h,{title:"Бронзовое оружие",children:(0,i.jsx)(s.p,{children:"Страх перед бронзовым оружием, обмазанным кровью человека, которого очаровали."})}),(0,i.jsx)(h,{title:"Требовательность магии",children:(0,i.jsx)(s.p,{children:"Магический арсенал Иеронима Анагносту требует времени и пространства действия на раскрытие в своем полном потенциале, слабо подходя к ведению одиночного боя лицом к лицу или быстрым не затяжным сражениям. К тому же Верховный Арбитр маг и ученный, связать его ближним боем особенно опытному бойцу, полагающему на физическую силу – значит поставить его в крайне невыгодное положение."})}),(0,i.jsx)(h,{title:"Ограниченная зона действия",children:(0,i.jsx)(s.p,{children:"Магия Верховного Арбитра, за исключением [Первенцев Отражения], крайне ограничена в зоне действия, вследствие чего Иероним в условиях обширного пространства не способен в полной мере навязывать темп боя в роли инициатора агрессии, тем более преследователя. Ибо перемещение [Отблеска Фатума] вслед за противником при выходе его из радиуса во время исполнения тактического отступления потребует отзыва всех зеркал, их повторного призыва в новом месте, а также повторения процесса их инфузии."})}),(0,i.jsx)(h,{title:"Намеренный контроль противника",children:(0,i.jsx)(s.p,{children:"Намеренный контроль противника [Отблеска Фатума] (концентрированность на их уничтожении), не позволит Иерониму в полной мере воспользоваться своими заклинаниями, фактически лишая его возможности внести какой-либо весомый вклад в битву."})}),(0,i.jsx)(h,{title:"Увечья",children:(0,i.jsx)(s.p,{children:"Правая рука и шрам под адамовым яблоком ввиду увечий еще менее прочны по сравнению с остальным телом. Достаточно сильное магическое воздействие агрессивной природы направленное на правую руку Господина Калейдоскопа может открыть шрамы и временно парализовать конечность."})}),(0,i.jsx)(h,{title:"Физическая слабость",children:(0,i.jsx)(s.p,{children:"Слаб физически."})})]})}),(0,i.jsx)(r,{title:"Связанные персонажи",children:(0,i.jsx)(d,{children:(0,i.jsx)(h,{title:"Ираклий Псомас",children:(0,i.jsx)(s.p,{children:"18 лет, перерождение горячо любимого племянника. Связаны небольшой безделушкой в виде розы, символизирующую клятву вечно оставаться на его стороне в независимости от обстоятельств."})})})})]}),(0,i.jsx)(x,{children:(0,i.jsx)(s.p,{children:"Неизвестность — это источник нового знания"})})]})}function n(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:n}={...(0,l.useMDXComponents)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(s,{...e})}):s(e)}])}]);